def transform(grid):
    h = len(grid)
    w = len(grid[0])
    horizontal = [r for r in range(h) if all(v == 6 for v in grid[r])]
    vertical = [c for c in range(w) if all(grid[r][c] == 6 for r in range(h))]
    if vertical and horizontal:
        mid_r = horizontal[0]
        mid_c = vertical[0]
        blocks = [
            [row[:mid_c] for row in grid[:mid_r]],
            [row[mid_c+1:] for row in grid[:mid_r]],
            [row[:mid_c] for row in grid[mid_r+1:]],
            [row[mid_c+1:] for row in grid[mid_r+1:]],
        ]
        orientation = "vertical"
        input_orientation = "square"
    elif horizontal:
        cuts = [-1] + horizontal + [h]
        blocks = [grid[cuts[i]+1:cuts[i+1]] for i in range(len(cuts)-1)]
        orientation = "horizontal"
    else:
        cuts = [-1] + vertical + [w]
        blocks = [[row[cuts[i]+1:cuts[i+1]] for row in grid] for i in range(len(cuts)-1)]
        orientation = "vertical"
    def color(block):
        return next(v for row in block for v in row if v not in (6, 7))
    blocks.sort(key=lambda b: (sum(v not in (6, 7) for row in b for v in row), -color(b)))
    if orientation == "vertical":
        out = []
        for i, block in enumerate(blocks):
            if i:
                out.append([6] * len(blocks[0][0]))
            out.extend([row[:] for row in block])
    else:
        out = []
        for r in range(len(blocks[0])):
            row = []
            for i, block in enumerate(blocks):
                if i:
                    row.append(6)
                row.extend(block[r])
            out.append(row)
    return out

